<?php
namespace App\Models; use App\Models\Concerns\InvalidatesStatistics; use Illuminate\Database\Eloquent\{Builder,Factories\HasFactory,Model}; use Illuminate\Database\Eloquent\Relations\HasMany; class Statistic extends Model { use HasFactory,InvalidatesStatistics; protected $fillable=['label','value','prefix','suffix','description','statistic_group','icon','source_note','source_url','as_of_date','status','is_featured','display_order','published_at','scheduled_for','archived_at','created_by','updated_by']; protected function casts():array{return ['as_of_date'=>'date','is_featured'=>'boolean','published_at'=>'datetime','scheduled_for'=>'datetime','archived_at'=>'datetime'];} public function homepageItems():HasMany{return $this->hasMany(HomepageItem::class);} public function scopePubliclyVisible(Builder $q):Builder{return $q->whereNull('archived_at')->where(fn(Builder $q)=>$q->where(fn(Builder $x)=>$x->where('status','published')->whereNotNull('published_at')->where('published_at','<=',now()))->orWhere(fn(Builder $x)=>$x->where('status','scheduled')->whereNotNull('scheduled_for')->where('scheduled_for','<=',now())));} public function isPubliclyVisible():bool{return $this->archived_at===null&&(($this->status==='published'&&$this->published_at?->lte(now()))||($this->status==='scheduled'&&$this->scheduled_for?->lte(now())));}}
